import{_ as o,C as a,o as n,c as s,E as r,a9 as t}from"./chunks/framework.asyjyako.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"PerfChecker.jl","text":"Measure how Julia code changes","tagline":"Compare time and allocations across versions, then profile what got slower.","image":{"src":"/assets/perfchecker-mark.png","alt":"PerfChecker"},"actions":[{"theme":"brand","text":"Quickstart","link":"/guide/overview"},{"theme":"alt","text":"Examples","link":"/tutorials/bibliography"},{"theme":"alt","text":"Use VS Code","link":"/interfaces/vscode"}]},"features":[{"title":"Measure a test","details":"Run an existing TestItem and inspect its time and allocations.","link":"/guide/overview","linkText":"Try the quickstart"},{"title":"Compare versions","details":"Measure the same operation across releases or Git revisions.","link":"/tutorials/comparisons","linkText":"Compare results"},{"title":"Find expensive calls","details":"Inspect CPU, wall-time and allocation profiles from saved runs.","link":"/tutorials/comparisons","linkText":"Read a profile"},{"title":"Open a notebook","details":"Prepare a suite, inspect saved results and launch selected checks in Pluto.","link":"/interfaces/pluto","linkText":"Use Pluto"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),h={name:"index.md"};function p(u,e,c,f,m,d){const i=a("MaintainerLink"),l=a("HomeMeasurements");return n(),s("div",null,[r(i),e[0]||(e[0]=t('<p><a id="From-a-passing-test-to-a-performance-comparison"></a></p><h2 id="What-it-does" tabindex="-1">What it does <a class="header-anchor" href="#What-it-does" aria-label="Permalink to &quot;What it does {#What-it-does}&quot;">​</a></h2><ul><li><p>Runs existing Julia <code>@testitem</code>s, or operations you define.</p></li><li><p>Measures in a separate worker process, so the UI is not measured.</p></li><li><p>Saves results as portable run bundles. Every interface reads the same files.</p></li><li><p>Compares releases, Git revisions and Julia runtimes.</p></li><li><p>Profiles CPU, wall time and allocations when a timing changes.</p></li></ul>',3)),r(l),e[1]||(e[1]=t('<h2 id="Where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#Where-to-start" aria-label="Permalink to &quot;Where to start {#Where-to-start}&quot;">​</a></h2><ul><li><p>New here? Start with <a href="./guide/overview">your first comparison</a>.</p></li><li><p>Investigating a change? Follow <a href="./tutorials/comparisons">the Bibliography case study</a>.</p></li><li><p>Define a larger experiment with <a href="./software-suites">suites and CI</a>.</p></li></ul><p><a id="Use-the-results-in-your-own-workflow"></a></p><h2 id="Interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#Interfaces" aria-label="Permalink to &quot;Interfaces {#Interfaces}&quot;">​</a></h2><ul><li><p><a href="./interfaces/vscode">VS Code</a> — run one item while editing.</p></li><li><p><a href="./interfaces/web-studio">Web interface (Oxygen)</a> — select workloads in a browser.</p></li><li><p><a href="./interfaces/pluto">Pluto</a> — editable notebooks with explicit launch controls.</p></li><li><p><a href="./interfaces/repl">REPL</a> — plan and inspect results in Julia.</p></li><li><p><a href="./interfaces/tachikoma">Tachikoma</a> — interactive terminal selection.</p></li><li><p><a href="./interfaces/visualization">Makie</a> — figures from saved runs.</p></li><li><p><a href="./interfaces/documentation">Documenter</a> — include saved results in documentation.</p></li></ul><h2 id="Examples" tabindex="-1">Examples <a class="header-anchor" href="#Examples" aria-label="Permalink to &quot;Examples {#Examples}&quot;">​</a></h2><ul><li><p><a href="./tutorials/bibliography">Bibliography</a> — compare nine releases, then investigate export costs.</p></li><li><p><a href="./real-packages/datastructures">DataStructures</a> — 35 containers over eight years.</p></li><li><p><a href="./real-packages/oxygen">Oxygen</a> — HTTP handlers and real network traffic.</p></li></ul><h2 id="Contribute" tabindex="-1">Contribute <a class="header-anchor" href="#Contribute" aria-label="Permalink to &quot;Contribute {#Contribute}&quot;">​</a></h2><p><a href="https://github.com/Mirage-Interactive-Fr/PerfChecker.jl/issues" target="_blank" rel="noreferrer">Report a problem</a>, <a href="./contributing/">improve code, documentation or an example</a>, or open a pull request.</p><details class="details custom-block"><summary>Built with the Julia community</summary><p>PerfChecker.jl brings together work from many projects. We thank their maintainers, contributors, and the Julia community for making these workflows possible.</p><ul><li><p><strong>Measure and profile:</strong> <a href="https://github.com/JuliaCI/BenchmarkTools.jl" target="_blank" rel="noreferrer">BenchmarkTools</a> and <a href="https://github.com/LilithHafner/Chairmarks.jl" target="_blank" rel="noreferrer">Chairmarks</a> provide timing and allocation measurements. Julia&#39;s <a href="https://docs.julialang.org/en/v1/stdlib/Profile/" target="_blank" rel="noreferrer">Profile and Profile.Allocs</a> provide stack profiles; <a href="https://github.com/JuliaCI/CoverageTools.jl" target="_blank" rel="noreferrer">CoverageTools</a> supports line-level allocation analysis.</p></li><li><p><strong>Check correctness and investigate:</strong> <a href="https://github.com/julia-testitems/TestItems.jl" target="_blank" rel="noreferrer">TestItems</a> and <a href="https://github.com/julia-testitems/TestItemRunner.jl" target="_blank" rel="noreferrer">TestItemRunner</a> define and run checks; <a href="https://github.com/Seelengrab/PropCheck.jl" target="_blank" rel="noreferrer">PropCheck</a> and <a href="https://github.com/Seelengrab/Supposition.jl" target="_blank" rel="noreferrer">Supposition</a> supply generated cases that PerfChecker freezes into repeatable corpora. Optional analyzers <a href="https://github.com/aviatesk/JET.jl" target="_blank" rel="noreferrer">JET</a>, <a href="https://github.com/JuliaLang/AllocCheck.jl" target="_blank" rel="noreferrer">AllocCheck</a>, <a href="https://github.com/JuliaDebug/SnoopCompile.jl" target="_blank" rel="noreferrer">SnoopCompile</a>, and <a href="https://github.com/JuliaTesting/Aqua.jl" target="_blank" rel="noreferrer">Aqua</a> examine inference, allocation paths, compilation, and package quality.</p></li><li><p><strong>Choose an interface:</strong> <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">VS Code</a> and the <a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">MCP community</a> support editor and agent workflows. <a href="https://github.com/JuliaPluto/Pluto.jl" target="_blank" rel="noreferrer">Pluto</a> and <a href="https://github.com/JuliaPluto/PlutoUI.jl" target="_blank" rel="noreferrer">PlutoUI</a> support reactive notebooks; <a href="https://github.com/OxygenFramework/Oxygen.jl" target="_blank" rel="noreferrer">Oxygen</a> and <a href="https://github.com/JuliaWeb/HTTP.jl" target="_blank" rel="noreferrer">HTTP</a> support the Web interface. <a href="https://github.com/MakieOrg/Makie.jl" target="_blank" rel="noreferrer">Makie</a>, its CairoMakie and WGLMakie backends, and <a href="https://github.com/SimonDanisch/Bonito.jl" target="_blank" rel="noreferrer">Bonito</a> support interactive views and graphical exports; <a href="https://github.com/JuliaPlots/UnicodePlots.jl" target="_blank" rel="noreferrer">UnicodePlots</a> and <a href="https://github.com/kahliburke/Tachikoma.jl" target="_blank" rel="noreferrer">Tachikoma</a> support terminal views.</p></li><li><p><strong>Preserve and share evidence:</strong> <a href="https://github.com/JuliaPluto/Malt.jl" target="_blank" rel="noreferrer">Malt</a> supplies isolated workers, <a href="https://github.com/JuliaDynamics/DrWatson.jl" target="_blank" rel="noreferrer">DrWatson</a> supports experiment storage, and <a href="https://github.com/timholy/FlameGraphs.jl" target="_blank" rel="noreferrer">FlameGraphs</a> and <a href="https://github.com/JuliaPerf/PProf.jl" target="_blank" rel="noreferrer">PProf</a> support profile export.</p></li><li><p><strong>Configure and qualify:</strong> <a href="https://github.com/JuliaPackaging/Preferences.jl" target="_blank" rel="noreferrer">Preferences.jl</a> supports project-local defaults in PerfChecker 1.1.0 and later. <a href="https://github.com/JuliaCI/PkgEval.jl" target="_blank" rel="noreferrer">PkgEval.jl</a> and the <a href="https://github.com/JuliaCI" target="_blank" rel="noreferrer">JuliaCI community</a> support package qualification in isolated test environments; PkgEval is not a performance-measurement backend.</p></li><li><p><strong>Explore optional workloads and counters:</strong> <a href="https://github.com/JuliaPerf/LinuxPerf.jl" target="_blank" rel="noreferrer">LinuxPerf</a> and <a href="https://github.com/JuliaPerf/LIKWID.jl" target="_blank" rel="noreferrer">LIKWID</a> support hardware-counter companions. Julia Threads and Distributed, <a href="https://github.com/JuliaParallel/Dagger.jl" target="_blank" rel="noreferrer">Dagger</a>, <a href="https://github.com/JuliaGPU/KernelAbstractions.jl" target="_blank" rel="noreferrer">KernelAbstractions</a>, and <a href="https://github.com/JuliaGPU/CUDA.jl" target="_blank" rel="noreferrer">CUDA</a> support scenarios when supplied by the workload.</p></li><li><p><strong>Document the results:</strong> <a href="https://github.com/JuliaDocs/Documenter.jl" target="_blank" rel="noreferrer">Documenter</a>, <a href="https://github.com/LuxDL/DocumenterVitepress.jl" target="_blank" rel="noreferrer">DocumenterVitepress</a>, and <a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a> power these guides and API references.</p></li></ul><details><summary>Additional foundations</summary><p>Core&#39;s data and source handling also depend on <a href="https://github.com/JuliaData/CSV.jl">CSV</a>, <a href="https://github.com/JuliaParallel/Hwloc.jl">Hwloc</a>, <a href="https://github.com/JuliaIO/JSON.jl">JSON</a>, <a href="https://github.com/JuliaLang/JuliaSyntax.jl">JuliaSyntax</a>, <a href="https://github.com/JuliaData/TypedTables.jl">TypedTables</a>, and <a href="https://github.com/JuliaData/YAML.jl">YAML</a>. We also thank the <a href="https://julialang.org/">Julia language</a>, compiler, runtime, and standard-library maintainers, including those of Base64, Dates, Downloads, Libdl, Pkg, Profile, Random, SHA, TOML, and UUIDs.</p><p>Development-only tests also use <a href="https://github.com/invenia/Intervals.jl">Intervals</a>, <a href="https://github.com/JuliaConstraints/PatternFolds.jl">PatternFolds</a>, and Julia&#39;s Test, Logging, and Sockets libraries.</p></details><p>Optional integrations require their packages; hardware and platform support vary. Thank you to everyone who builds, documents, tests, and maintains these tools.</p></details>',10))])}const k=o(h,[["render",p]]);export{b as __pageData,k as default};
